namespace Commerce.Operations.Api.Settlements;
public static class SettlementEndpoints{public static IEndpointRouteBuilder MapSettlementEndpoints(this IEndpointRouteBuilder endpoints){var group=endpoints.MapGroup("/api/settlements").RequireAuthorization().WithTags("Settlements");group.MapGet("",async(DateOnly from,DateOnly to,SettlementGateway gateway)=>Valid(from,to)?await Try(()=>gateway.ListAsync(from,to)):RangeError());group.MapPost("/rebuild",async(DateOnly from,DateOnly to,SettlementGateway gateway)=>Valid(from,to)?await Try(()=>gateway.RebuildAsync(from,to)):RangeError()).RequireAuthorization("AdminOnly");return endpoints;}private static bool Valid(DateOnly from,DateOnly to)=>from<=to&&to.DayNumber-from.DayNumber<=366;private static IResult RangeError()=>Results.ValidationProblem(new Dictionary<string,string[]>{{"range",["Date range must be 367 days or less."]}});private static async Task<IResult> Try<T>(Func<Task<T>> action){try{return Results.Ok(await action());}catch(SettlementGatewayException e){return Results.Problem(statusCode:(int)e.StatusCode,title:"Order engine request failed",detail:e.Message);}}}
